class OrderManager {

    private PaymentGateway paymentGateway;
    private InventoryStore inventoryStore;
    private EmailClient emailClient;
    private Logger logger;

    void placeOrder(Order order) {
        double total = order.items().stream().mapToDouble(Item::price).sum();
        boolean charged = paymentGateway.charge(order.customerId(), total);
        if (!charged) {
            logger.log("payment failed for order " + order.id());
            throw new PaymentException("charge declined");
        }
        for (Item item : order.items()) {
            inventoryStore.decrement(item.sku(), item.quantity());
        }
        emailClient.send(order.customerEmail(), "Order confirmed", buildReceiptText(order, total));
        logger.log("order placed " + order.id());
    }

    private String buildReceiptText(Order order, double total) {
        return "Thanks for your order, total: " + total;
    }
}

