class PaymentException {
public:
    PaymentException(const std::string& msg) : message(msg) {}
    std::string message;
};

class OrderManager {
private:
    PaymentGateway* paymentGateway;
    InventoryStore* inventoryStore;
    EmailClient* emailClient;
    Logger* logger;

    std::string buildReceiptText(const Order& order, double total) {
        return "Thanks for your order, total: " + std::to_string(total);
    }

public:
    void placeOrder(const Order& order) {
        double total = 0;
        for (const Item& item : order.items()) {
            total += item.price();
        }
        bool charged = paymentGateway->charge(order.customerId(), total);
        if (!charged) {
            logger->log("payment failed for order " + order.id());
            throw PaymentException("charge declined");
        }
        for (const Item& item : order.items()) {
            inventoryStore->decrement(item.sku(), item.quantity());
        }
        emailClient->send(order.customerEmail(), "Order confirmed", buildReceiptText(order, total));
        logger->log("order placed " + order.id());
    }
};

